    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Knowledge on the sequelae of Coronavirus Disease 2019 (COVID-19) remains limited due to the relatively recent onset of this pathology. However, the literature on other types of coronavirus infections prior to COVID-19 reports that patients may experience persistent symptoms after discharge.",
      "reason": "States the current state of knowledge (limited knowledge about COVID-19 sequelae) and highlights uncertainty by referencing prior coronavirus literature suggesting possible persistent symptoms."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To determine the prevalence of respiratory symptoms in survivors of hospital admission after COVID-19 infection. A living systematic review of five databases was performed in order to identify studies which reported the persistence of respiratory symptoms in COVID-19 patients after discharge.",
      "reason": "Explicitly states the purpose of the review (to determine prevalence of respiratory symptoms) and describes the conduct of a living systematic review, indicating the importance and need to quantify post-discharge respiratory symptoms."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence provided that the authors discussed existing similar systematic reviews, nor cited or explained the need relative to previous reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "To determine the prevalence of respiratory symptoms in survivors of hospital admission after COVID-19 infection.",
      "reason": "The review addresses prevalence of symptoms (observational focus), not intervention effects; therefore describing mechanisms of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "To determine the prevalence of respiratory symptoms in survivors of hospital admission after COVID-19 infection.",
      "reason": "The review is not assessing a complex intervention or delivery context, so a logic model of intervention components and outcomes is not applicable."
    }
  ],
  "confidence": 85
}

