{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria for the systematic review were a) randomised controlled trials (RCT) and observational studies (retrospective, prospective, crosssectional, longitudinal, case-control and cohort), b) whose objective was to determine the prevalence of respiratory symptoms in patients presenting with COVID-19, c) laboratory-confirmed COVID-19 infection by quantitative real-time polymerase chain reaction (qRT-PCR) or polymerase chain reaction dual fluorescence (PCR), d) hospitalised adult patients ( ≤ 18 years), e) follow-up from 30 days after Covid-19 infection, f) follow-up from 21 days after hospital discharge. The exclusion criteria were: a) systematic reviews, protocol studies, case reports, studies showing the effects of medical or other intervention. No other restrictions in eligibility criteria were applied.",
      "reason": "The text explicitly lists eligible study designs, the target question (prevalence of respiratory symptoms), confirmation method, population (hospitalised adults), and follow-up timing, as well as exclusion study types."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The exclusion criteria were: a) systematic reviews, protocol studies, case reports, studies showing the effects of medical or other intervention. No other restrictions in eligibility criteria were applied.",
      "reason": "The manuscript specifies some report characteristics (excluded study types; elsewhere a preprint was excluded per text_14/figure), but does not specify dissemination year or language restrictions, so report-characteristic criteria are only partially specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction is made between excluding studies because outcomes were not measured versus excluding because outcome results were not reported; the exclusions list (e.g. 'wrong outcome') does not document this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The report does not specify the groups used in each synthesis or link those groups to the comparisons defined in the review objectives; figures and text show numbers included in qualitative/quantitative synthesis but do not define synthesis groups or comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "The exclusion criteria were: a) systematic reviews, protocol studies, case reports, studies showing the effects of medical or other intervention. No other restrictions in eligibility criteria were applied.",
      "reason": "While some exclusions are listed, the manuscript does not provide rationales explaining notable restrictions on eligibility (for example, choice of follow-up thresholds or exclusion of certain designs); no justification is given in the provided text."
    }
  ],
  "confidence": 80
}

